import{_ as l,a0 as p,w as s,s as i,ao as d,I as n,x as t,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"六個開源軟件開發的“潛規則” | LCTT x X-CMD","titleTemplate":false,"description":"六個開源軟件開發的“潛規則” | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"六個開源軟件開發的“潛規則” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"六個開源軟件開發的“潛規則” | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170112 The 6 unwritten rules of open source development","title":"六個開源軟件開發的“潛規則”","tag":"201705","desc":""},"relativePath":"201705/20170112 The 6 unwritten rules of open source development.md","filePath":"[post].md"}'),u={name:"201705/20170112 The 6 unwritten rules of open source development.md"};function m(h,e,f,T,w,b){const a=p("Link");return s(),i("div",null,[e[13]||(e[13]=d('<h1 id="六個開源軟件開發的-潛規則" tabindex="-1">六個開源軟件開發的“潛規則” <a class="header-anchor" href="#六個開源軟件開發的-潛規則" aria-label="Permalink to “六個開源軟件開發的“潛規則””">​</a></h1><blockquote><p>你想成為開源項目中得意滿滿、功成名就的那個人嗎，那就要遵守下面的“潛規則”。</p></blockquote><p><img src="http://images.techhive.com/images/article/2016/12/09_opensource-100698477-large.jpg" alt="The 6 unwritten rules of open source development"></p><p>正如體育界不成文的規定一樣，這些規則基本上不會出現在官方文檔和正式記錄上。比如説，在棒球運動中，從比分領先時不要盜壘，到跑壘員跑了第一時也不要放棄四壞球保送。對於圈外人來講，這些東西很難懂，甚至覺得沒什麼意義。但是對於那些想成為 MVP 的隊員來説，這些都是理所當然的。</p><p>軟件開發，特別是開源軟件開發中，也有一套不成文的規定。和其它的團隊運動一樣，這些規定很大程度上決定了開源社區如何看待一名開發者，特別是新加入社區的開發者。</p><h3 id="運行之前先調試" tabindex="-1">運行之前先調試 <a class="header-anchor" href="#運行之前先調試" aria-label="Permalink to “運行之前先調試”">​</a></h3><p>在參與社區之前，比如開放源代碼或者其它什麼的，你需要做一些基本工作。對於有眼界的開源貢獻者，這意味這你需要理解社區的目標，並學習應該從哪裏起步。人人都想貢獻源代碼，但是隻有少量的人做過準備，並且樂意、同時也有能力完成這項艱苦卓絕的工作：測試補丁、複審代碼、撰寫文檔、修正錯誤。所有的這些不受待見的任務在一個健康的社區中都是必要的。</p><p>為什麼要在優雅地寫代碼前做這些呢？這是一種信任，更重要的是，不要只關注自己開發的功能，而是要關注整個社區的動向。</p><h3 id="填坑而不是挖坑" tabindex="-1">填坑而不是挖坑 <a class="header-anchor" href="#填坑而不是挖坑" aria-label="Permalink to “填坑而不是挖坑”">​</a></h3><p>當你在某個社區中建立起自己的聲望，那麼很有必要全面瞭解該項目和代碼。不要停留於任務狀態上，而是要去鑽研項目本身，理解那些超出你擅長範圍之外的知識。不要只把自己的理解侷限於開發者，這樣會讓你着眼於讓你的代碼有更大的影響，而不只是你那一畝三分地。</p><p>打個比方，你已經完成了一個網絡模組的測試版本。你測試了一下，覺得不錯。然後你把它開放到社區，想要更多的人測試。結果發現，當它以特定的方式部署時，有可能會破壞安全設置，還可能導致主存儲泄露。如果你將代碼視為一個整體時問題就可以迎刃而解，而不是孤立地看待問題。這表明，你要對項目各個部分如何與其他人協作交互有比較深入的理解。讓你的補丁填坑而不是挖坑。這樣你朝成為社區精英的目標上又前進了一大步。</p><h3 id="不投放代碼炸彈" tabindex="-1">不投放代碼炸彈 <a class="header-anchor" href="#不投放代碼炸彈" aria-label="Permalink to “不投放代碼炸彈”">​</a></h3><p>代碼提交完畢後你的工作還沒結束。如果代碼被接受，還會有一些關於這些更改的討論和常見的問答，還要做測試。你要確保你可以準時提交，努力去理解如何在不影響社區其他成員的情況下，改進代碼和補丁。</p><h3 id="助己之前先助人" tabindex="-1">助己之前先助人 <a class="header-anchor" href="#助己之前先助人" aria-label="Permalink to “助己之前先助人”">​</a></h3><p>開源社區不是自相殘殺的叢林世界，我們更看重項目的價值而非個體的貢獻和成功。如果你想給自己加分，讓自己成為更重要的社區成員、讓社區接納你的代碼，那就努力幫助別人。如果你熟悉網絡部分，那就去複審網絡部分，用你的專業技能讓整個代碼更加優雅。道理很簡單，頂級的審查者經常和頂級的貢獻者打交道。你幫助的人越多，你就越有價值。</p><h3 id="打磨拋光才算完" tabindex="-1">打磨拋光才算完 <a class="header-anchor" href="#打磨拋光才算完" aria-label="Permalink to “打磨拋光才算完”">​</a></h3><p>作為一個開發者，你很可能希望為開源項目解決一個特定的痛點。或許你想要運行在一個目前還不支持的系統上，抑或你很希望改革社區目前使用的安全技術。想要引進新技術，特別是比較有爭議的技術，最好的辦法就是讓人無法拒絕它。你需要透徹地瞭解底層代碼，考慮每個極端情況。在不影響已實現功能的前提下增加新功能。不僅僅是完成就行，還要在特性的完善上下功夫。</p><h3 id="不離不棄方始終" tabindex="-1">不離不棄方始終 <a class="header-anchor" href="#不離不棄方始終" aria-label="Permalink to “不離不棄方始終”">​</a></h3><p>開源社區也有許多玩玩就算的人，但是承諾了就不要輕易失信。不要就因為提交被拒就離開社區。找出原因，修正錯誤，然後再試一試。當你開發時候，要和整個代碼庫保持一致，確保即使項目發生變化而你的補丁仍然可用。不要把你的代碼留給別人修復，要自己修復。這樣可以在社區形成良好的風氣，每個人都自己改。</p><hr><p>這些“潛規則”看上去很簡單，但是還是有許多開源項目的貢獻者並沒有遵守。這樣做的開發者不僅可以為成功地推動他們自己的項目，而且也有助於開源社區。</p><p>作者簡介：</p><p>Matt Hicks 是 Red Hat 軟件工程的副主席，也是 Red Hat 開源合作團隊的奠基成員之一。他歷時十五年，在軟件工程中擔任多種職務：開發，運行，架構，管理。</p><hr>',24)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),o(a,{href:"http://www.infoworld.com/article/3156776/open-source-tools/the-6-unwritten-rules-of-open-source-development.html"},{default:r(()=>[...e[0]||(e[0]=[t("http://www.infoworld.com/article/3156776/open-source-tools/the-6-unwritten-rules-of-open-source-development.html",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=t("作者：",-1)),o(a,{href:"http://www.infoworld.com/blog/new-tech-forum/"},{default:r(()=>[...e[2]||(e[2]=[t("Matt Hicks",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),o(a,{href:"https://github.com/Taylor1024"},{default:r(()=>[...e[3]||(e[3]=[t("Taylor1024",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const g=l(u,[["render",m]]);export{k as __pageData,g as default};
